def handler(**params):
    import requests
    import json

    # Validate required parameters
    query = params.get('query')
    if not query:
        return {"error": "query parameter is required"}

    # Perplexity API configuration
    api_key = "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"
    url = "https://api.perplexity.ai/chat/completions"

    # Build the request payload
    payload = {
        "model": "sonar-pro",
        "messages": [
            {
                "role": "system",
                "content": "You are a helpful search assistant. Provide comprehensive and accurate search results."
            },
            {
                "role": "user",
                "content": query
            }
        ],
        "temperature": 0.2,
        "top_p": 0.9,
        "search_domain_filter": [],
        "return_images": False,
        "return_related_questions": True,
        "search_recency_filter": params.get('search_recency_filter', 'month'),
        "frequency_penalty": 0,
        "presence_penalty": 0
    }

    headers = {
        "Authorization": f"Bearer {api_key}",
        "Content-Type": "application/json"
    }

    try:
        # Make the API request
        response = requests.post(url, headers=headers, json=payload, timeout=30)
        response.raise_for_status()

        # Parse the response
        data = response.json()

        # Extract the main content
        if 'choices' in data and len(data['choices']) > 0:
            content = data['choices'][0]['message']['content']

            # Build structured response
            result = {
                "success": True,
                "query": query,
                "answer": content,
                "model": data.get('model', 'sonar-pro'),
                "usage": data.get('usage', {})
            }

            # Add citations if available
            if 'citations' in data:
                result['citations'] = data['citations']

            return result
        else:
            return {
                "success": False,
                "error": "No response from Perplexity API",
                "query": query
            }

    except requests.exceptions.Timeout:
        return {
            "success": False,
            "error": "Request timed out after 30 seconds",
            "query": query
        }
    except requests.exceptions.RequestException as e:
        return {
            "success": False,
            "error": f"API request failed: {str(e)}",
            "query": query
        }
    except Exception as e:
        return {
            "success": False,
            "error": f"Unexpected error: {str(e)}",
            "query": query
        }
